```cpp
#include <bits/stdc++.h>
using namespace std;using ll=long long;
int main(){
    ios::sync_with_stdio(false);cin.tie(nullptr);
    int T;cin>>T;while(T--){
        int n,q;string s;cin>>n>>q>>s;
        ll ones=count(s.begin(),s.end(),'1'),weighted=0;
        for(int i=0;i+1<n;i++)if(s[i]!=s[i+1])weighted+=1LL*(i+1)*(n-i-1);
        auto answer=[&](){return (weighted+ones*(n-ones))/2;};
        cout<<answer();
        while(q--){
            int p;cin>>p;--p;
            // 翻转一位只切换它左右两条边界；边界 i 被 i*(n-i) 个子串包含。
            for(int j:{p-1,p})if(j>=0&&j+1<n){
                weighted+=(s[j]!=s[j+1]?-1LL:1LL)*(j+1)*(n-j-1);
            }
            ones+=(s[p]=='0'?1:-1);s[p]=(s[p]=='0'?'1':'0');
            cout<<' '<<answer();
        }
        cout<<'\n';
    }
}
```

### 易错点

边界权重按从一开始的 $i$ 计算；字符先读旧值再更新计数。不同字符位置对只对应一个子串，不乘二。

